-- =====================================================================
-- ARC by Lunarovx · contenido editable desde el panel de coach
-- Pégalo en Supabase > SQL Editor después de 0001_arc.sql y dale a Run.
-- =====================================================================

create table if not exists public.content_quotes (
  id text primary key default gen_random_uuid()::text,
  text text not null, who text not null, source text, why text,
  kind text not null default 'cita' check (kind in ('cita', 'leccion')),
  active boolean not null default true,
  updated_at timestamptz not null default now()
);
create table if not exists public.content_exercises (
  id text primary key, grp text not null, name text not null,
  muscle text, equip text, simple text, tip text, note text,
  lift text not null default '' check (lift in ('', 'squat', 'deadlift', 'bench', 'pull')),
  unit text not null default '' check (unit in ('', 's', 'min')),
  sort int not null default 999,
  updated_at timestamptz not null default now()
);
create table if not exists public.content_foods (
  id text primary key, name text not null,
  p numeric not null default 0, c numeric not null default 0, f numeric not null default 0,
  tags text[] not null default '{}',
  updated_at timestamptz not null default now()
);
create table if not exists public.content_recipes (
  id text primary key default gen_random_uuid()::text,
  slot text not null, mode text not null check (mode in ('sencilla', 'sanji')), name text not null,
  items jsonb not null, how text, steps jsonb not null default '[]', plate text,
  tupper boolean not null default false, active boolean not null default true, sort int not null default 999,
  updated_at timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['content_quotes', 'content_exercises', 'content_foods', 'content_recipes'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "leer" on public.%I', t);
    execute format('create policy "leer" on public.%I for select to authenticated using (true)', t);
    execute format('drop policy if exists "coach edita" on public.%I', t);
    execute format('create policy "coach edita" on public.%I for all to authenticated using (public.is_coach()) with check (public.is_coach())', t);
  end loop;
end $$;

insert into public.content_quotes (id, text, who, source, why, kind, active)
select id, text, who, source, why, kind, active from jsonb_populate_recordset(null::public.content_quotes, $arc$[{"id": "q001", "text": "Un perdedor puede superar a un genio a base de esfuerzo.", "who": "Rock Lee", "source": "Naruto", "why": "Lee no podía usar ninjutsu y aun así se ganó un sitio entre los mejores. Aquí nadie necesita talento para subir de nivel.", "kind": "cita", "active": true}, {"id": "q002", "text": "No voy a huir ni a retirar mi palabra. Ese es mi camino ninja.", "who": "Naruto Uzumaki", "source": "Naruto", "why": "Si te has dicho que hoy entrenas, hoy entrenas. Cúmplete a ti misma.", "kind": "cita", "active": true}, {"id": "q003", "text": "Ve más allá. ¡Plus Ultra!", "who": "All Might", "source": "My Hero Academia", "why": "Esa última repetición con buena técnica es tu Plus Ultra de hoy.", "kind": "cita", "active": true}, {"id": "q004", "text": "Tú también puedes ser un héroe.", "who": "All Might", "source": "My Hero Academia", "why": "Se lo dijo a un chaval sin poderes. Ese chaval acabó siendo el número uno.", "kind": "cita", "active": true}, {"id": "q005", "text": "Si ganas, vives. Si pierdes, mueres. Si no luchas, no puedes ganar.", "who": "Eren Yeager", "source": "Attack on Titan", "why": "Para los días en que el sofá te llama: presentarte ya es luchar.", "kind": "cita", "active": true}, {"id": "q006", "text": "¡Entregad vuestros corazones!", "who": "Erwin Smith", "source": "Attack on Titan", "why": "Hoy dalo todo en el entreno. Mañana descansas.", "kind": "cita", "active": true}, {"id": "q007", "text": "Este mundo es cruel, y aun así es tan hermoso.", "who": "Mikasa Ackerman", "source": "Attack on Titan", "why": "Entrenar cuesta, y verte más fuerte merece cada gota de sudor.", "kind": "cita", "active": true}, {"id": "q008", "text": "Elige aquello de lo que menos te vayas a arrepentir.", "who": "Levi Ackerman", "source": "Attack on Titan", "why": "¿Te arrepentirás más de ir al gym cansada o de no haber ido? Ya lo sabes.", "kind": "cita", "active": true}, {"id": "q009", "text": "Tranquilo, soy el más fuerte.", "who": "Satoru Gojo", "source": "Jujutsu Kaisen", "why": "Dilo antes de ponerte bajo la barra. La confianza también se entrena.", "kind": "cita", "active": true}, {"id": "q010", "text": "Eres fuerte, así que ayuda a los demás.", "who": "El abuelo de Itadori", "source": "Jujutsu Kaisen", "why": "Tu fuerza también sirve para animar a la amiga que no se atreve a empezar.", "kind": "cita", "active": true}, {"id": "q011", "text": "Huir de lo que te hace daño no tiene nada de malo.", "who": "Reigen Arataka", "source": "Mob Psycho 100", "why": "Si un gym o una rutina te hacen sentir mal, cámbialos. Seguir entrenando es lo que importa.", "kind": "cita", "active": true}, {"id": "q012", "text": "¿Cuándo muere una persona? Cuando es olvidada.", "who": "Hiriluk", "source": "One Piece", "why": "Lo que no apuntas ni repites, se olvida. Registra tu serie.", "kind": "cita", "active": true}, {"id": "q013", "text": "¡Los sueños de las personas nunca terminan!", "who": "Barbanegra", "source": "One Piece", "why": "Di en voz alta qué quieres conseguir, aunque alguien se ría.", "kind": "cita", "active": true}, {"id": "q014", "text": "¡Voy a ser el Rey de los Piratas!", "who": "Monkey D. Luffy", "source": "One Piece", "why": "Luffy lo grita desde el capítulo uno sin vergüenza. Ponle nombre a tu meta.", "kind": "cita", "active": true}, {"id": "q015", "text": "Cuando decidí perseguir mi sueño, ya había dejado atrás mi vida.", "who": "Roronoa Zoro", "source": "One Piece", "why": "Comprometerte de verdad quita muchas dudas de golpe.", "kind": "cita", "active": true}, {"id": "q016", "text": "Nada… No ha pasado nada.", "who": "Roronoa Zoro", "source": "One Piece", "why": "Cuando acabas destrozada la pierna y aun así sonríes al salir del gym.", "kind": "cita", "active": true}, {"id": "q017", "text": "No todo el que se esfuerza triunfa, pero todo el que ha triunfado se ha esforzado.", "who": "Kamogawa", "source": "Hajime no Ippo", "why": "El esfuerzo no te asegura el resultado. Es lo único que te da opciones.", "kind": "cita", "active": true}, {"id": "q018", "text": "Quiero saber qué significa ser fuerte.", "who": "Ippo Makunouchi", "source": "Hajime no Ippo", "why": "Ippo empezó por esa pregunta y lleva más de mil capítulos respondiéndola.", "kind": "cita", "active": true}, {"id": "q019", "text": "No tienes enemigos. Nadie tiene enemigos.", "who": "Thors", "source": "Vinland Saga", "why": "Ni la chica de al lado ni tu cuerpo son tus enemigos. Entrena desde ahí.", "kind": "cita", "active": true}, {"id": "q020", "text": "Un verdadero guerrero no necesita espada.", "who": "Thors", "source": "Vinland Saga", "why": "La fuerza de verdad se nota en cómo tratas a los demás.", "kind": "cita", "active": true}, {"id": "q021", "text": "No debo huir. No debo huir. No debo huir.", "who": "Shinji Ikari", "source": "Neon Genesis Evangelion", "why": "Shinji lo repite temblando y se sube igual. Puedes ir al gym con miedo.", "kind": "cita", "active": true}, {"id": "q022", "text": "Soy infantil y odio perder.", "who": "L", "source": "Death Note", "why": "Tu mejor rival es tu marca de la semana pasada. Gánale.", "kind": "cita", "active": true}, {"id": "q023", "text": "Si vas a golpear algo, golpéalo hasta romperlo.", "who": "Tooru Oikawa", "source": "Haikyuu!!", "why": "Cuando algo te cueste, insiste hasta que deje de costarte.", "kind": "cita", "active": true}, {"id": "q024", "text": "¡Arde, corazón!", "who": "Kyojuro Rengoku", "source": "Demon Slayer", "why": "Para cuando la motivación se apaga a mitad de entreno.", "kind": "cita", "active": true}, {"id": "q025", "text": "Levántate y camina. Sigue adelante. Tienes un buen par de piernas.", "who": "Edward Elric", "source": "Fullmetal Alchemist", "why": "Tienes piernas. Hoy toca usarlas.", "kind": "cita", "active": true}, {"id": "q026", "text": "Levántate.", "who": "Sung Jinwoo", "source": "Solo Leveling", "why": "El cazador más débil del mundo subió de nivel con su misión diaria. Tu misión hoy: levantarte e ir.", "kind": "cita", "active": true}, {"id": "q027", "text": "El esfuerzo no vale nada si no crees en ti misma.", "who": "Naruto Uzumaki", "source": "Naruto", "why": "Entrena a tu cabeza para creer en lo que estás construyendo.", "kind": "cita", "active": true}, {"id": "q028", "text": "No importa lo fuerte que golpees. Importa lo fuerte que te pueden golpear y seguir avanzando.", "who": "Rocky Balboa", "source": "Rocky Balboa", "why": "Una mala semana, un catarro, exámenes. Lo importante es volver el lunes.", "kind": "cita", "active": true}, {"id": "q029", "text": "Vas a comer rayos y vas a cagar truenos.", "who": "Mickey", "source": "Rocky III", "why": "Mood de día de pierna.", "kind": "cita", "active": true}, {"id": "q030", "text": "Un paso a la vez, un golpe a la vez, un asalto a la vez.", "who": "Rocky Balboa", "source": "Creed", "why": "No pienses en el año entero. Piensa en esta serie.", "kind": "cita", "active": true}, {"id": "q031", "text": "Protégete siempre.", "who": "Frankie Dunn", "source": "Million Dollar Baby", "why": "Cuida tu técnica, tu descanso y tu cabeza. Sin eso no hay progreso que dure.", "kind": "cita", "active": true}, {"id": "q032", "text": "Si hay magia en el boxeo, es la de pelear más allá de lo que aguantas.", "who": "Scrap", "source": "Million Dollar Baby", "why": "Maggie empezó a los 31 sin que nadie quisiera entrenarla. Nunca es tarde.", "kind": "cita", "active": true}, {"id": "q033", "text": "Nunca dejes que nadie te diga que no puedes hacer algo. Ni siquiera yo.", "who": "Chris Gardner", "source": "En busca de la felicidad", "why": "Y menos la vocecita que te dice que eso no es para ti.", "kind": "cita", "active": true}, {"id": "q034", "text": "No hay ingrediente secreto.", "who": "El padre de Po", "source": "Kung Fu Panda", "why": "No hay atajos. Hay constancia.", "kind": "cita", "active": true}, {"id": "q035", "text": "Ayer es historia, mañana es un misterio, pero hoy es un regalo.", "who": "Maestro Oogway", "source": "Kung Fu Panda", "why": "Solo puedes entrenar hoy. Hazlo.", "kind": "cita", "active": true}, {"id": "q036", "text": "Dar cera, pulir cera.", "who": "Señor Miyagi", "source": "Karate Kid", "why": "Los básicos aburridos son los que luego te salvan.", "kind": "cita", "active": true}, {"id": "q037", "text": "Hazlo o no lo hagas, pero no lo intentes.", "who": "Yoda", "source": "El Imperio contraataca", "why": "Ve a por la serie con la cabeza puesta.", "kind": "cita", "active": true}, {"id": "q038", "text": "¿Por qué nos caemos? Para aprender a levantarnos.", "who": "Thomas Wayne", "source": "Batman Begins", "why": "Un mal entreno también enseña.", "kind": "cita", "active": true}, {"id": "q039", "text": "Hay una diferencia entre conocer el camino y recorrerlo.", "who": "Morfeo", "source": "Matrix", "why": "Saber la teoría está bien. Ir al gym está mejor.", "kind": "cita", "active": true}, {"id": "q040", "text": "El miedo es el asesino de la mente.", "who": "Paul Atreides", "source": "Dune", "why": "El miedo a hacerlo mal no te puede quitar el entreno.", "kind": "cita", "active": true}, {"id": "q041", "text": "Lo único que debemos decidir es qué hacer con el tiempo que se nos ha dado.", "who": "Gandalf", "source": "El Señor de los Anillos", "why": "Una hora al día te cambia el año.", "kind": "cita", "active": true}, {"id": "q042", "text": "Cualquiera puede cocinar.", "who": "Auguste Gusteau", "source": "Ratatouille", "why": "Hoy prueba una receta del Modo Sanji. Remy te mira.", "kind": "cita", "active": true}, {"id": "q043", "text": "Odiaba cada minuto de entrenamiento, pero me decía: no abandones. Sufre ahora y vive el resto de tu vida como un campeón.", "who": "Muhammad Ali", "source": "Boxeo", "why": "Ni a Ali le apetecía siempre. Lo hacía igual.", "kind": "cita", "active": true}, {"id": "q044", "text": "He fallado más de 9.000 tiros en mi carrera. Por eso tengo éxito.", "who": "Michael Jordan", "source": "Baloncesto", "why": "Cada serie fallida es un dato para la siguiente.", "kind": "cita", "active": true}, {"id": "q045", "text": "Todo lo negativo, la presión, los retos, es una oportunidad para crecer.", "who": "Kobe Bryant", "source": "Baloncesto", "why": "Ese peso que te intimida es tu próxima oportunidad.", "kind": "cita", "active": true}, {"id": "q046", "text": "Solo los disciplinados son libres.", "who": "Eliud Kipchoge", "source": "Maratón", "why": "La disciplina te ahorra decidir cada día si vas o no.", "kind": "cita", "active": true}, {"id": "q047", "text": "No temo al hombre que ha practicado 10.000 patadas una vez, sino al que ha practicado una patada 10.000 veces.", "who": "Bruce Lee", "source": "Artes marciales", "why": "Domina la sentadilla antes de buscar la variante rara.", "kind": "cita", "active": true}, {"id": "q048", "text": "Sé agua, amigo mío.", "who": "Bruce Lee", "source": "Artes marciales", "why": "Si la máquina está ocupada, cambia de ejercicio. Adáptate y sigue.", "kind": "cita", "active": true}, {"id": "q049", "text": "Nadie va a venir a salvarte.", "who": "David Goggins", "source": "Ultrafondo", "why": "Duro, pero liberador: el cambio depende de ti.", "kind": "cita", "active": true}, {"id": "q050", "text": "El dolor es inevitable. El sufrimiento es opcional.", "who": "Haruki Murakami", "source": "De qué hablo cuando hablo de correr", "why": "Las piernas arden, pero lo que te cuentas mientras lo eliges tú.", "kind": "cita", "active": true}, {"id": "q051", "text": "Lo que se interpone en el camino se convierte en el camino.", "who": "Marco Aurelio", "source": "Meditaciones", "why": "Si una lesión te frena un ejercicio, trabaja lo que sí puedes.", "kind": "cita", "active": true}, {"id": "q052", "text": "Ningún ser humano es libre si no es dueño de sí mismo.", "who": "Epicteto", "source": "Filosofía estoica", "why": "Ganarle a la pereza también es libertad.", "kind": "cita", "active": true}, {"id": "q053", "text": "No es que tengamos poco tiempo, es que perdemos mucho.", "who": "Séneca", "source": "Sobre la brevedad de la vida", "why": "Una hora de entreno es menos de lo que se va en scroll.", "kind": "cita", "active": true}, {"id": "q054", "text": "Somos lo que hacemos repetidamente.", "who": "Will Durant, sobre Aristóteles", "source": "Filosofía", "why": "Un día de gym no cambia nada. Cien seguidos, sí.", "kind": "cita", "active": true}, {"id": "q055", "text": "Quien tiene un porqué para vivir puede soportar casi cualquier cómo.", "who": "Friedrich Nietzsche", "source": "Filosofía", "why": "Ten claro para qué entrenas. El cómo se aguanta mejor.", "kind": "cita", "active": true}, {"id": "q056", "text": "Cuando ya no podemos cambiar una situación, tenemos el reto de cambiarnos a nosotros mismos.", "who": "Viktor Frankl", "source": "El hombre en busca de sentido", "why": "No controlas tu genética. Sí lo que haces con ella.", "kind": "cita", "active": true}, {"id": "q057", "text": "Un viaje de mil millas comienza con un solo paso.", "who": "Lao Tse", "source": "Tao Te Ching", "why": "Tu primer paso puede ser abrir la app y mirar tu rutina.", "kind": "cita", "active": true}, {"id": "q058", "text": "Cada acción que haces es un voto por la persona que quieres ser.", "who": "James Clear", "source": "Hábitos atómicos", "why": "Cada vaso de agua y cada serie cuentan como voto.", "kind": "cita", "active": true}, {"id": "q059", "text": "No subes al nivel de tus metas. Caes al nivel de tus sistemas.", "who": "James Clear", "source": "Hábitos atómicos", "why": "Por eso aquí subes de nivel con hábitos, no con propósitos de año nuevo.", "kind": "cita", "active": true}, {"id": "q060", "text": "Nadie puede hacerte sentir inferior sin tu consentimiento.", "who": "Eleanor Roosevelt", "source": "Política y activismo", "why": "Tu sitio en la zona de pesas es tuyo.", "kind": "cita", "active": true}, {"id": "q061", "text": "Pies, ¿para qué os quiero si tengo alas para volar?", "who": "Frida Kahlo", "source": "Diario", "why": "Frida pintó con dolor toda su vida. Tu cuerpo puede más de lo que crees.", "kind": "cita", "active": true}, {"id": "q062", "text": "Nada en la vida debe ser temido, solo comprendido.", "who": "Marie Curie", "source": "Ciencia", "why": "Entender la técnica quita el miedo a la barra.", "kind": "cita", "active": true}, {"id": "q063", "text": "Atribuyo mi éxito a esto: nunca di ni acepté una excusa.", "who": "Florence Nightingale", "source": "Enfermería", "why": "La fundadora de la enfermería moderna, también en el gym.", "kind": "cita", "active": true}, {"id": "q064", "text": "Quiérete a ti misma. Habla por ti misma.", "who": "BTS", "source": "Discurso en la ONU", "why": "Entrenar por amor a tu cuerpo, no por castigo.", "kind": "cita", "active": true}]$arc$::jsonb)
on conflict (id) do nothing;

insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort)
select id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort from jsonb_populate_recordset(null::public.content_exercises, $arc$[{"id": "ARC-001", "grp": "Pecho", "name": "Flexiones", "muscle": "Pectoral, tríceps, hombro anterior", "equip": "Peso corporal", "simple": "Apoyada en las manos y las puntas de los pies, bajas el pecho hacia el suelo flexionando los codos y vuelves a subir con el cuerpo recto como una tabla.", "tip": "Codos a unos 45° del cuerpo, no abiertos en cruz. Si no puedes con el suelo, apoya las manos en un banco y ve bajando la altura con las semanas.", "note": "", "lift": "", "unit": "", "sort": 0}, {"id": "ARC-002", "grp": "Pecho", "name": "Press plano con mancuernas", "muscle": "Pectoral", "equip": "Mancuernas", "simple": "Lo mismo que el press de banca con barra, pero cada brazo se mueve de forma independiente, así que exige más estabilidad.", "tip": "Baja las mancuernas hasta notar un estiramiento cómodo en el pecho, no hasta tocar el cuerpo. Bajar de más solo mete tensión en el hombro.", "note": "", "lift": "", "unit": "", "sort": 1}, {"id": "ARC-003", "grp": "Pecho", "name": "Press inclinado con mancuernas", "muscle": "Pectoral superior", "equip": "Mancuernas", "simple": "Igual que el anterior pero en un banco inclinado, para darle más trabajo a la parte alta del pecho.", "tip": "Un ángulo de 30-45° es suficiente. Si inclinas demasiado el banco, dejas de trabajar pecho y empiezas a trabajar hombro.", "note": "", "lift": "", "unit": "", "sort": 2}, {"id": "ARC-004", "grp": "Pecho", "name": "Press de pecho en máquina", "muscle": "Pectoral", "equip": "Máquina", "simple": "Empujas el peso hacia delante desde el pecho, con el recorrido ya guiado por la máquina.", "tip": "Aprieta los omóplatos entre sí antes de empezar cada repetición. Si no lo haces, el hombro se lleva parte del trabajo que debería hacer el pecho.", "note": "", "lift": "", "unit": "", "sort": 3}, {"id": "ARC-005", "grp": "Pecho", "name": "Aperturas en máquina (pec deck)", "muscle": "Pectoral", "equip": "Máquina", "simple": "Llevas los brazos desde abiertos hasta juntos por delante del pecho, en un movimiento de \"abrazo\".", "tip": "Codos ligeramente flexionados y fijos durante todo el recorrido. Si los flexionas y estiras, se convierte en press, no en aislamiento de pecho.", "note": "", "lift": "", "unit": "", "sort": 4}, {"id": "ARC-006", "grp": "Pecho", "name": "Fondos en paralelas o banco", "muscle": "Pectoral inferior, tríceps", "equip": "Peso corporal", "simple": "Bajas el cuerpo flexionando los codos y subes empujando, usando tu propio peso como carga.", "tip": "Inclina un poco el torso hacia delante si quieres más pecho; mantente más vertical si quieres más tríceps.", "note": "", "lift": "", "unit": "", "sort": 5}, {"id": "ARC-007", "grp": "Espalda", "name": "Dominadas", "muscle": "Dorsal ancho, bíceps", "equip": "Peso corporal", "simple": "Colgada de una barra con las palmas mirando hacia delante, tiras del cuerpo hacia arriba hasta pasar la barbilla por encima de la barra y bajas controlada.", "tip": "Antes de doblar los codos, baja los hombros alejándolos de las orejas. Piensa en llevar los codos al suelo, no en tirar con los brazos.", "note": "No te preocupes si aún no te sale: en el vídeo tienes variantes (asistida, con banda y negativas).", "lift": "pull", "unit": "", "sort": 6}, {"id": "ARC-008", "grp": "Espalda", "name": "Dominada asistida", "muscle": "Dorsal ancho, bíceps", "equip": "Máquina / banda", "simple": "Versión de dominada con ayuda de un contrapeso o una banda elástica, para quienes todavía no hacen la dominada completa.", "tip": "Controla también la bajada, no solo la subida. Bajar lento es lo que más construye fuerza para llegar a la dominada sin ayuda.", "note": "", "lift": "", "unit": "", "sort": 7}, {"id": "ARC-009", "grp": "Espalda", "name": "Jalón al pecho agarre prono", "muscle": "Dorsal ancho", "equip": "Polea", "simple": "Tiras de la barra desde arriba hacia el pecho, sentada con las piernas ancladas.", "tip": "Antes de tirar con el brazo, lleva primero los hombros hacia abajo y atrás. Así activas la espalda antes que el bíceps.", "note": "", "lift": "", "unit": "", "sort": 8}, {"id": "ARC-010", "grp": "Espalda", "name": "Jalón al pecho agarre supino", "muscle": "Dorsal ancho, bíceps", "equip": "Polea", "simple": "Igual que el jalón normal, pero con las palmas mirando hacia ti y las manos a la anchura de los hombros. Trabaja el dorsal con algo más de bíceps.", "tip": "Lleva los codos hacia las costillas y saca pecho al llegar abajo. Con este agarre es fácil tirar solo con el bíceps; piensa en la espalda.", "note": "", "lift": "", "unit": "", "sort": 9}, {"id": "ARC-011", "grp": "Espalda", "name": "Jalón unilateral en máquina (dorsal)", "muscle": "Dorsal ancho", "equip": "Máquina", "simple": "Tiras de un asa con un solo brazo, llevando el codo hacia la cadera. Así trabajas cada lado de la espalda por separado y notas mejor el dorsal.", "tip": "Inclina un poco el torso hacia el lado que trabajas y no gires el cuerpo para ayudarte. Aguanta 1 segundo en la contracción.", "note": "", "lift": "", "unit": "", "sort": 10}, {"id": "ARC-012", "grp": "Espalda", "name": "Remo en T", "muscle": "Dorsal, trapecio medio, romboides", "equip": "Barra / máquina", "simple": "Inclinada hacia delante con una barra anclada por un extremo, tiras del peso hacia el abdomen. Se trabaja toda la espalda con mucha carga.", "tip": "Mantén el pecho alto y la espalda recta, y lleva los codos hacia atrás pegados al cuerpo. Si se te redondea la espalda, baja el peso.", "note": "", "lift": "", "unit": "", "sort": 11}, {"id": "ARC-013", "grp": "Espalda", "name": "Remo agarre neutro sentado", "muscle": "Dorsal, romboides", "equip": "Polea / máquina", "simple": "Sentada frente a la polea o la máquina, tiras del agarre con las palmas enfrentadas hacia tu abdomen, juntando los omóplatos.", "tip": "Primero lleva los hombros hacia atrás y luego los codos. Aguanta 1 segundo y vuelve despacio, sin inclinarte hacia delante al estirar.", "note": "", "lift": "", "unit": "", "sort": 12}, {"id": "ARC-014", "grp": "Espalda", "name": "Remo agarre prono en máquina sentado", "muscle": "Dorsal alto, trapecio, romboides", "equip": "Máquina", "simple": "Sentada con el pecho apoyado, tiras de las asas con las palmas hacia abajo y los codos abiertos, para trabajar la parte alta y media de la espalda.", "tip": "Agarre algo más abierto que los hombros. Lleva primero los hombros atrás y después los codos. Controla la vuelta: ahí se construye.", "note": "", "lift": "", "unit": "", "sort": 13}, {"id": "ARC-015", "grp": "Espalda", "name": "Remo con mancuerna a una mano", "muscle": "Dorsal, romboides", "equip": "Mancuerna", "simple": "Apoyas una rodilla y una mano en un banco, y tiras de la mancuerna con el otro brazo hacia la cadera.", "tip": "Evita rotar el torso al tirar. Si giras el cuerpo para ayudarte, es que el peso es demasiado alto.", "note": "", "lift": "", "unit": "", "sort": 14}, {"id": "ARC-016", "grp": "Espalda", "name": "Remo con barra", "muscle": "Dorsal, trapecio, romboides", "equip": "Barra", "simple": "Inclinada hacia delante con una barra en las manos, tiras de ella hacia el abdomen y la bajas controlada.", "tip": "Fija el torso desde el principio y no lo muevas. Si necesitas balancearte para subir la barra, baja el peso.", "note": "", "lift": "", "unit": "", "sort": 15}, {"id": "ARC-017", "grp": "Espalda", "name": "Pull-over con mancuerna", "muscle": "Dorsal ancho, pectoral", "equip": "Mancuerna", "simple": "Tumbada en un banco, bajas una mancuerna con los brazos casi rectos por detrás de la cabeza y la vuelves a subir, trabajando espalda y pecho a la vez.", "tip": "Piensa en mover el peso en un arco, con los brazos casi rectos. Si flexionas los codos, se convierte en un ejercicio de tríceps.", "note": "", "lift": "", "unit": "", "sort": 16}, {"id": "ARC-018", "grp": "Espalda", "name": "Reverse fly con mancuernas", "muscle": "Deltoide posterior, espalda alta", "equip": "Mancuernas", "simple": "Inclinada hacia delante, abres los brazos hacia los lados con mancuernas, como si quisieras juntar los omóplatos.", "tip": "Piensa en llevar los codos hacia fuera, no las manos. Usa poco peso: el hombro posterior es un músculo pequeño.", "note": "", "lift": "", "unit": "", "sort": 17}, {"id": "ARC-019", "grp": "Espalda", "name": "Reverse fly en máquina", "muscle": "Deltoide posterior, espalda alta", "equip": "Máquina", "simple": "Sentada mirando hacia el respaldo de la máquina, llevas los brazos hacia atrás y hacia los lados para trabajar la parte de atrás del hombro.", "tip": "Ajusta el asiento para que las asas queden a la altura del hombro y no encojas los hombros hacia las orejas.", "note": "", "lift": "", "unit": "", "sort": 18}, {"id": "ARC-020", "grp": "Espalda", "name": "Face pull", "muscle": "Deltoide posterior, trapecio, manguito", "equip": "Polea", "simple": "Con una cuerda en una polea a la altura de la cara, tiras hacia ti separando las manos, como si fueras a tocarte las orejas con los pulgares.", "tip": "Tira hacia la cara abriendo las manos y piensa en enseñar los codos. Usa poco peso y mucho control.", "note": "", "lift": "", "unit": "", "sort": 19}, {"id": "ARC-021", "grp": "Espalda", "name": "Peso muerto convencional", "muscle": "Espalda baja, glúteo, isquiotibiales", "equip": "Barra", "simple": "Levantas una barra cargada del suelo hasta quedar completamente de pie, manteniendo la espalda recta todo el recorrido.", "tip": "Antes de tirar, empuja el suelo con los pies y aprieta las axilas como si guardaras algo debajo. La barra siempre pegada a las piernas.", "note": "", "lift": "deadlift", "unit": "", "sort": 20}, {"id": "ARC-022", "grp": "Hombro", "name": "Press militar con mancuernas", "muscle": "Deltoide anterior y lateral, tríceps", "equip": "Mancuernas", "simple": "De pie o sentada, empujas las mancuernas desde la altura de los hombros hacia arriba.", "tip": "Aprieta el abdomen como si te fueran a dar un golpe en el estómago. Evita que la zona lumbar se arquee al empujar.", "note": "", "lift": "", "unit": "", "sort": 21}, {"id": "ARC-023", "grp": "Hombro", "name": "Press de hombro en máquina", "muscle": "Deltoide anterior y lateral", "equip": "Máquina", "simple": "Empujas el peso hacia arriba por encima de la cabeza, sentada, con el recorrido guiado.", "tip": "Baja solo hasta la altura de la barbilla/oreja, no más. Bajar en exceso mete tensión innecesaria en la articulación del hombro.", "note": "", "lift": "", "unit": "", "sort": 22}, {"id": "ARC-024", "grp": "Hombro", "name": "Press Arnold", "muscle": "Deltoide (las tres porciones)", "equip": "Mancuernas", "simple": "Press de hombro con mancuernas, pero empiezas con las palmas mirando hacia ti y vas rotando las muñecas mientras subes, hasta acabar con las palmas hacia delante arriba.", "tip": "Gira las muñecas de forma fluida mientras subes y usa menos peso que en el press normal. Es un ejercicio más técnico.", "note": "", "lift": "", "unit": "", "sort": 23}, {"id": "ARC-025", "grp": "Hombro", "name": "Elevaciones laterales con mancuernas", "muscle": "Deltoide lateral", "equip": "Mancuernas", "simple": "De pie, levantas los brazos hacia los lados hasta la altura del hombro.", "tip": "Imagina que estás vertiendo agua de una jarra al subir (muñeca ligeramente rotada hacia abajo). Ayuda a que trabaje el hombro y no el trapecio.", "note": "", "lift": "", "unit": "", "sort": 24}, {"id": "ARC-026", "grp": "Hombro", "name": "Elevaciones laterales en máquina", "muscle": "Deltoide lateral", "equip": "Máquina", "simple": "Sentada, abres los brazos hacia los lados contra las almohadillas hasta la altura de los hombros. La máquina guía el recorrido.", "tip": "Empuja con los codos, no con las manos. No subas por encima de la altura de los hombros y no encojas el trapecio.", "note": "", "lift": "", "unit": "", "sort": 25}, {"id": "ARC-027", "grp": "Hombro", "name": "Elevaciones laterales en polea", "muscle": "Deltoide lateral", "equip": "Polea", "simple": "Lo mismo que con mancuernas, pero con el cable de una polea baja, lo que mantiene tensión constante en todo el recorrido.", "tip": "Colócate algo alejada de la polea y deja que el brazo cruce ligeramente por delante del cuerpo al empezar; así el músculo trabaja desde el primer grado del movimiento.", "note": "", "lift": "", "unit": "", "sort": 26}, {"id": "ARC-028", "grp": "Hombro", "name": "Elevaciones frontales con mancuernas", "muscle": "Deltoide anterior", "equip": "Mancuernas", "simple": "De pie, levantas una o dos mancuernas hacia delante hasta la altura del hombro, con los brazos casi rectos.", "tip": "Sube solo hasta la altura de los ojos y baja lento. Si balanceas el cuerpo, la mancuerna pesa de más.", "note": "", "lift": "", "unit": "", "sort": 27}, {"id": "ARC-029", "grp": "Bíceps", "name": "Curl de bíceps en máquina", "muscle": "Bíceps braquial", "equip": "Máquina", "simple": "Sentada o de pie, flexionas el codo contra resistencia para acercar el peso al hombro.", "tip": "No uses impulso de los hombros. Si te cuesta subir sin balancearte, el peso es demasiado alto.", "note": "", "lift": "", "unit": "", "sort": 28}, {"id": "ARC-030", "grp": "Bíceps", "name": "Curl predicador", "muscle": "Bíceps braquial", "equip": "Máquina", "simple": "Con los brazos apoyados en un soporte inclinado, flexionas los codos para subir el peso y bajas hasta casi estirar el brazo. El soporte evita que hagas trampa.", "tip": "Baja del todo, hasta estirar el codo sin perder la tensión, y no despegues las axilas del apoyo al subir.", "note": "", "lift": "", "unit": "", "sort": 29}, {"id": "ARC-031", "grp": "Bíceps", "name": "Curl con mancuernas agarre abierto", "muscle": "Bíceps braquial", "equip": "Mancuernas", "simple": "Variante con los codos y las manos algo separados del cuerpo: subes las mancuernas hacia los hombros girando las palmas hacia arriba.", "tip": "Separa los codos solo un poco del torso y no los adelantes al subir. Controla la bajada.", "note": "", "lift": "", "unit": "", "sort": 30}, {"id": "ARC-032", "grp": "Bíceps", "name": "Curl con mancuernas agarre cerrado", "muscle": "Bíceps braquial", "equip": "Mancuernas", "simple": "Variante con los codos pegados al torso y las manos cerca de las caderas: subes las mancuernas hacia el centro del pecho.", "tip": "Pega los codos a las costillas y que no se muevan hacia delante. Si te cuesta subir sin balancearte, el peso es demasiado.", "note": "", "lift": "", "unit": "", "sort": 31}, {"id": "ARC-033", "grp": "Bíceps", "name": "Curl de bíceps con barra en polea", "muscle": "Bíceps braquial", "equip": "Polea", "simple": "De pie frente a una polea baja con una barra, flexionas los codos para subirla hacia el pecho y bajas despacio.", "tip": "Bajada controlada, estirando hasta abajo sin perder la tensión. Al subir, cuidado con no elevar los hombros.", "note": "", "lift": "", "unit": "", "sort": 32}, {"id": "ARC-034", "grp": "Tríceps", "name": "Extensión de tríceps en polea", "muscle": "Tríceps (las tres cabezas)", "equip": "Polea", "simple": "De pie frente a una polea alta, extiendes el codo empujando una cuerda o barra hacia abajo.", "tip": "Codos pegados al cuerpo y fijos, como si estuvieran clavados ahí. Solo se mueve el antebrazo.", "note": "", "lift": "", "unit": "", "sort": 33}, {"id": "ARC-035", "grp": "Tríceps", "name": "Extensión de tríceps trasnuca en polea", "muscle": "Tríceps (cabeza larga)", "equip": "Polea", "simple": "De espaldas a la polea, con la cuerda detrás de la cabeza, estiras los codos hacia delante y arriba y los vuelves a doblar. Trabaja mucho la parte larga del tríceps.", "tip": "Mantén los codos apuntando hacia delante, cerca de las orejas, y que solo se muevan los antebrazos. Si los codos se abren, baja el peso.", "note": "", "lift": "", "unit": "", "sort": 34}, {"id": "ARC-036", "grp": "Tríceps", "name": "Extensión de tríceps trasnuca con mancuerna de pie", "muscle": "Tríceps (cabeza larga)", "equip": "Mancuerna", "simple": "De pie, sujetas una mancuerna con las dos manos por encima de la cabeza, la bajas detrás de la nuca doblando los codos y la subes estirando los brazos.", "tip": "Codos apuntando al frente y cerca de la cabeza. Aprieta el abdomen para no arquear la espalda al subir.", "note": "", "lift": "", "unit": "", "sort": 35}, {"id": "ARC-037", "grp": "Tríceps", "name": "Fondos de tríceps en banco", "muscle": "Tríceps", "equip": "Peso corporal", "simple": "Apoyas las manos en un banco detrás de ti y bajas el cuerpo flexionando los codos.", "tip": "Cuanto más alejados tengas los pies del banco, más difícil se hace. Empieza con las rodillas flexionadas si es tu primera vez.", "note": "", "lift": "", "unit": "", "sort": 36}, {"id": "ARC-038", "grp": "Cuádriceps", "name": "Prensa horizontal", "muscle": "Cuádriceps, glúteo", "equip": "Máquina", "simple": "Empujas una plataforma con peso usando las piernas, sentada en un ángulo prácticamente plano.", "tip": "No bloquees la rodilla del todo arriba. Quedarte a medio estirar mantiene la tensión en el músculo en vez de pasarla a la articulación.", "note": "", "lift": "", "unit": "", "sort": 37}, {"id": "ARC-039", "grp": "Cuádriceps", "name": "Prensa inclinada (45°)", "muscle": "Cuádriceps, glúteo", "equip": "Máquina", "simple": "La versión más común de prensa, en ángulo, donde empujas el peso hacia arriba con las piernas.", "tip": "La posición de los pies cambia el enfoque: más arriba en la plataforma = más glúteo y femoral; más abajo = más cuádriceps.", "note": "", "lift": "", "unit": "", "sort": 38}, {"id": "ARC-040", "grp": "Cuádriceps", "name": "Prensa vertical (acostada)", "muscle": "Cuádriceps, glúteo", "equip": "Máquina", "simple": "Te tumbas bocarriba y empujas el peso hacia arriba, en vertical sobre ti.", "tip": "Cuidado con bajar demasiado: si la zona lumbar se despega del respaldo, es que has bajado más de lo que tu movilidad permite de forma segura.", "note": "", "lift": "", "unit": "", "sort": 39}, {"id": "ARC-041", "grp": "Cuádriceps", "name": "Extensión de cuádriceps", "muscle": "Cuádriceps", "equip": "Máquina", "simple": "Sentada, extiendes las piernas contra una resistencia hasta quedar rectas.", "tip": "Agárrate a las asas laterales tirando hacia abajo. Fija tu cuerpo y evita que compenses con la cadera.", "note": "", "lift": "", "unit": "", "sort": 40}, {"id": "ARC-042", "grp": "Cuádriceps", "name": "Sentadilla con multipower", "muscle": "Cuádriceps, glúteo", "equip": "Multipower", "simple": "Sentadilla con la barra fijada a unos raíles, que guían el movimiento verticalmente.", "tip": "Coloca los pies un poco más adelantados que en una sentadilla libre. Como la barra va recta, necesitas ese ajuste para no forzar el tobillo.", "note": "", "lift": "squat", "unit": "", "sort": 41}, {"id": "ARC-043", "grp": "Cuádriceps", "name": "Sentadilla goblet con mancuerna", "muscle": "Cuádriceps, glúteo", "equip": "Mancuerna", "simple": "Sentadilla sujetando una mancuerna o pesa rusa pegada al pecho con ambas manos.", "tip": "Usa el peso como \"contrapeso\" para mantenerte erguida: te ayuda a bajar más profundo sin perder el equilibrio.", "note": "", "lift": "", "unit": "", "sort": 42}, {"id": "ARC-044", "grp": "Cuádriceps", "name": "Sumo en máquina de cinturón (belt squat)", "muscle": "Cuádriceps, glúteo, aductores", "equip": "Máquina", "simple": "Te pones un cinturón enganchado a la máquina y haces sentadilla con las piernas bien abiertas, sin que el peso cargue sobre la columna.", "tip": "Empuja el suelo con todo el pie y abre las rodillas hacia las puntas de los pies. Si se te cierran hacia dentro, baja el peso.", "note": "", "lift": "", "unit": "", "sort": 43}, {"id": "ARC-045", "grp": "Cuádriceps", "name": "Zancadas con mancuernas", "muscle": "Cuádriceps, glúteo", "equip": "Mancuernas", "simple": "Con una mancuerna en cada mano, das un paso largo hacia delante y bajas doblando ambas rodillas, luego vuelves a la posición inicial.", "tip": "Da un paso lo bastante largo para que la rodilla de delante no sobrepase la punta del pie. Mira al frente, no al suelo.", "note": "", "lift": "", "unit": "", "sort": 44}, {"id": "ARC-046", "grp": "Cuádriceps", "name": "Zancadas en Smith", "muscle": "Cuádriceps, glúteo", "equip": "Multipower", "simple": "La misma zancada, pero con la barra guiada en los raíles de la máquina apoyada en los hombros, para mayor estabilidad.", "tip": "Coloca los pies un poco más adelantados que la barra. Así la rodilla delantera no se va hacia delante y trabajas más glúteo y cuádriceps.", "note": "", "lift": "", "unit": "", "sort": 45}, {"id": "ARC-047", "grp": "Cuádriceps", "name": "Step up en banco", "muscle": "Cuádriceps, glúteo", "equip": "Banco / peso corporal", "simple": "Subes a un banco o cajón con una pierna, apoyando todo el peso en ella hasta quedar de pie arriba, y bajas controlado.", "tip": "Empuja con el talón de la pierna que sube y no te ayudes con el pie de abajo. Elige una altura que te permita bajar con control.", "note": "", "lift": "", "unit": "", "sort": 46}, {"id": "ARC-048", "grp": "Cuádriceps", "name": "Step up con polea", "muscle": "Cuádriceps, glúteo", "equip": "Polea + banco", "simple": "El mismo movimiento de subir al banco, pero con una polea baja enganchada a la cintura o los hombros para añadir resistencia extra.", "tip": "Mantén el cable siempre tenso y no te impulses con la pierna de atrás. Si el cable tira de ti hacia delante, el peso es demasiado.", "note": "", "lift": "", "unit": "", "sort": 47}, {"id": "ARC-049", "grp": "Femoral", "name": "Femoral tumbado", "muscle": "Isquiotibiales", "equip": "Máquina", "simple": "Tumbada boca abajo, flexionas las rodillas llevando los talones hacia el glúteo contra resistencia.", "tip": "No levantes la cadera del banco al flexionar. Si la cadera sube, estás usando glúteo en vez de femoral.", "note": "", "lift": "", "unit": "", "sort": 48}, {"id": "ARC-050", "grp": "Femoral", "name": "Femoral sentado", "muscle": "Isquiotibiales", "equip": "Máquina", "simple": "Sentada, con las piernas estiradas sobre un rodillo, flexionas las rodillas llevando el rodillo hacia abajo/atrás.", "tip": "Mantén la espalda pegada al respaldo durante todo el recorrido; despegarla resta tensión al músculo que estás trabajando.", "note": "", "lift": "", "unit": "", "sort": 49}, {"id": "ARC-051", "grp": "Femoral", "name": "Peso muerto rumano con mancuernas", "muscle": "Isquiotibiales, glúteo", "equip": "Mancuernas", "simple": "Con las piernas casi rectas, bajas las mancuernas pegadas a las piernas manteniendo la espalda neutra, y vuelves a subir.", "tip": "La sensación de estiramiento en la parte de atrás del muslo es tu límite de bajada, no una distancia fija. Cuando notes ese tope, para ahí.", "note": "", "lift": "", "unit": "", "sort": 50}, {"id": "ARC-052", "grp": "Femoral", "name": "Peso muerto rumano a una mano", "muscle": "Isquiotibiales, glúteo", "equip": "Mancuerna", "simple": "Con una mancuerna en una mano, haces una bisagra de cadera: llevas el glúteo hacia atrás, bajas la mancuerna pegada a la pierna y vuelves a subir.", "tip": "Baja en 3-4 segundos y haz una micropausa abajo. Mantén la cadera cuadrada, sin girar el torso hacia el lado de la mancuerna.", "note": "", "lift": "", "unit": "", "sort": 51}, {"id": "ARC-053", "grp": "Femoral", "name": "Buenos días", "muscle": "Isquiotibiales, glúteo, lumbar", "equip": "Barra", "simple": "Con una barra ligera sobre la espalda alta, llevas la cadera hacia atrás inclinando el torso con la espalda recta y vuelves a subir.", "tip": "Empieza con muy poco peso. Baja hasta notar el estiramiento del femoral manteniendo la espalda recta; ese es tu límite de recorrido.", "note": "", "lift": "", "unit": "", "sort": 52}, {"id": "ARC-054", "grp": "Glúteo y cadera", "name": "Hip thrust con barra", "muscle": "Glúteo mayor", "equip": "Barra", "simple": "La versión con más carga: te apoyas en el banco con una barra con peso sobre la cadera (normalmente con una almohadilla protectora).", "tip": "Mira hacia abajo, no hacia delante, y aprieta el glúteo arriba 1-2 segundos. Si notas la zona lumbar, has subido demasiado.", "note": "", "lift": "", "unit": "", "sort": 53}, {"id": "ARC-055", "grp": "Glúteo y cadera", "name": "Hip thrust a una pierna", "muscle": "Glúteo mayor", "equip": "Peso corporal / banco", "simple": "Igual que el hip thrust normal, pero con una sola pierna apoyada y la otra estirada en el aire, para trabajar cada lado por separado.", "tip": "Empieza por la pierna que peor te sale y repite el mismo número de repeticiones en la otra. Mantén la cadera nivelada, sin girar.", "note": "", "lift": "", "unit": "", "sort": 54}, {"id": "ARC-056", "grp": "Glúteo y cadera", "name": "Hip thrust con banda elástica", "muscle": "Glúteo mayor y medio", "equip": "Banda elástica", "simple": "El mismo movimiento, con una banda elástica rodeando las rodillas que te obliga a empujarlas hacia fuera mientras subes.", "tip": "Empuja las rodillas hacia fuera durante toda la repetición. Si se juntan, baja la carga.", "note": "", "lift": "", "unit": "", "sort": 55}, {"id": "ARC-057", "grp": "Glúteo y cadera", "name": "Patada de glúteo en máquina", "muscle": "Glúteo mayor", "equip": "Máquina", "simple": "Empujas una plataforma hacia atrás con una pierna, en una máquina específica para glúteo.", "tip": "No uses impulso ni balanceo del cuerpo. El movimiento debe salir solo de la cadera hacia atrás, despacio.", "note": "", "lift": "", "unit": "", "sort": 56}, {"id": "ARC-058", "grp": "Glúteo y cadera", "name": "Patada de glúteo a cuatro patas", "muscle": "Glúteo mayor", "equip": "Peso corporal", "simple": "Apoyada en manos y rodillas, llevas una pierna hacia atrás y arriba manteniendo la rodilla flexionada.", "tip": "Aprieta el glúteo con fuerza en la parte más alta del movimiento durante 1 segundo antes de bajar.", "note": "", "lift": "", "unit": "", "sort": 57}, {"id": "ARC-059", "grp": "Glúteo y cadera", "name": "Patada de rana", "muscle": "Glúteo mayor", "equip": "Multipower / banco", "simple": "Apoyada en un banco frente al multipower, empujas la barra hacia arriba con la planta del pie y la rodilla flexionada. Trabaja el glúteo sin cargar la espalda.", "tip": "Agárrate bien al banco y mantén las piernas algo más abiertas que los hombros. Empuja con el glúteo, no con la zona lumbar.", "note": "", "lift": "", "unit": "", "sort": 58}, {"id": "ARC-060", "grp": "Glúteo y cadera", "name": "Abducción de cadera en máquina", "muscle": "Glúteo medio", "equip": "Máquina", "simple": "Sentada, separas las piernas hacia fuera contra resistencia.", "tip": "Inclínate ligeramente hacia delante en el asiento. Cambia el ángulo y mejora cuánto trabaja el glúteo frente a la cadera.", "note": "", "lift": "", "unit": "", "sort": 59}, {"id": "ARC-061", "grp": "Glúteo y cadera", "name": "Aducción de cadera en máquina", "muscle": "Aductores", "equip": "Máquina", "simple": "Sentada con las piernas abiertas contra las almohadillas, las cierras juntando los muslos y vuelves a abrir despacio. Trabaja la cara interna del muslo.", "tip": "Aguanta 1 segundo con las piernas juntas y controla la apertura en 3 segundos. No dejes que el peso te abra de golpe.", "note": "", "lift": "", "unit": "", "sort": 60}, {"id": "ARC-062", "grp": "Gemelo", "name": "Gemelo de pie en máquina", "muscle": "Gemelo", "equip": "Máquina", "simple": "De pie, te elevas sobre las puntas de los pies contra resistencia sobre los hombros.", "tip": "Baja el talón por debajo del nivel de la plataforma para estirar bien antes de volver a subir. El recorrido completo es lo que marca la diferencia aquí.", "note": "", "lift": "", "unit": "", "sort": 61}, {"id": "ARC-063", "grp": "Gemelo", "name": "Gemelo sentado en máquina", "muscle": "Sóleo", "equip": "Máquina", "simple": "Sentada, con el peso apoyado sobre las rodillas, te elevas sobre las puntas de los pies.", "tip": "Esta versión trabaja más la parte interna del gemelo (sóleo) que la de pie. Si solo haces una variante, te falta la otra.", "note": "", "lift": "", "unit": "", "sort": 62}, {"id": "ARC-064", "grp": "Abdomen", "name": "Crunch abdominal en máquina", "muscle": "Recto abdominal", "equip": "Máquina", "simple": "Sentada, flexionas el torso hacia delante contra resistencia.", "tip": "El movimiento es de la columna (te curvas), no de la cadera. Si \"doblas\" por la cintura sin curvar la espalda, no estás trabajando el abdomen de forma óptima.", "note": "", "lift": "", "unit": "", "sort": 63}, {"id": "ARC-065", "grp": "Abdomen", "name": "Crunch en polea (de rodillas)", "muscle": "Recto abdominal", "equip": "Polea", "simple": "De rodillas frente a una polea alta, flexionas el torso hacia abajo sujetando una cuerda junto a la cara.", "tip": "El movimiento sale de curvar la columna hacia abajo, no de bajar la cabeza ni tirar con los brazos. Los brazos solo sujetan el peso.", "note": "", "lift": "", "unit": "", "sort": 64}, {"id": "ARC-066", "grp": "Abdomen", "name": "Plancha", "muscle": "Core (transverso, recto)", "equip": "Peso corporal", "simple": "Mantienes el cuerpo recto apoyado en antebrazos y puntas de los pies, sin moverte.", "tip": "Aprieta los glúteos durante todo el ejercicio. Evita que la cadera se hunda, que es el fallo más común.", "note": "", "lift": "", "unit": "s", "sort": 65}, {"id": "ARC-067", "grp": "Abdomen", "name": "Elevación de piernas", "muscle": "Abdomen inferior, flexores de cadera", "equip": "Peso corporal", "simple": "Levantas las piernas (rectas o flexionadas) usando el abdomen, en vez del impulso de las caderas.", "tip": "Si notas que trabaja más la zona lumbar o la cadera que el abdomen, flexiona más las rodillas hasta que sea manejable con buena técnica.", "note": "", "lift": "", "unit": "", "sort": 66}, {"id": "ARC-068", "grp": "Abdomen", "name": "Bicicleta", "muscle": "Oblicuos, recto abdominal", "equip": "Peso corporal", "simple": "Tumbada bocarriba, alternas llevar el codo contrario hacia la rodilla contraria, en un movimiento de pedaleo.", "tip": "Hazlo despacio y controlado. El beneficio real está en la rotación controlada, no en la velocidad.", "note": "", "lift": "", "unit": "", "sort": 67}, {"id": "ARC-X01", "grp": "Cuádriceps", "name": "Sentadilla búlgara en Smith", "muscle": "Cuádriceps, glúteo", "equip": "Multipower + banco", "simple": "Con el empeine de atrás apoyado en un banco y la barra guiada sobre la espalda, bajas en vertical doblando la rodilla de delante.", "tip": "Pie de delante más adelantado = más glúteo; más cerca de la barra = más cuádriceps.", "note": "", "lift": "", "unit": "", "sort": 68}, {"id": "ARC-X02", "grp": "Femoral", "name": "Peso muerto rumano en Smith", "muscle": "Isquiotibiales, glúteo", "equip": "Multipower", "simple": "Bisagra de cadera con la barra guiada: llevas el glúteo hacia atrás y la barra baja pegada a las piernas.", "tip": "Para cuando notes el estiramiento del femoral, no cuando la barra llegue abajo.", "note": "", "lift": "", "unit": "", "sort": 69}, {"id": "ARC-X03", "grp": "Glúteo y cadera", "name": "Patada de glúteo en polea", "muscle": "Glúteo mayor", "equip": "Polea", "simple": "Con la tobillera enganchada a una polea baja, llevas la pierna hacia atrás desde la cadera y vuelves despacio.", "tip": "Inclínate un poco hacia delante y no arquees la zona lumbar al subir la pierna.", "note": "", "lift": "", "unit": "", "sort": 70}, {"id": "ARC-X04", "grp": "Pecho", "name": "Press banca con barra", "muscle": "Pectoral, tríceps", "equip": "Barra", "simple": "Tumbada en el banco, bajas la barra hasta el pecho y la empujas hasta estirar los brazos.", "tip": "Omóplatos juntos y pies firmes en el suelo; la barra baja a la altura del esternón.", "note": "", "lift": "bench", "unit": "", "sort": 71}, {"id": "ARC-X05", "grp": "Cuádriceps", "name": "Sentadilla con barra", "muscle": "Cuádriceps, glúteo", "equip": "Barra", "simple": "Con la barra sobre la espalda alta, bajas flexionando cadera y rodillas y vuelves a subir.", "tip": "Rodillas en la línea de las puntas de los pies y pecho alto todo el recorrido.", "note": "", "lift": "squat", "unit": "", "sort": 72}, {"id": "CARDIO", "grp": "Cardio", "name": "Cardio (cinta inclinada, bici o elíptica)", "muscle": "Corazón y piernas", "equip": "Máquina", "simple": "Ritmo en el que puedas hablar pero te cueste un poco.", "tip": "Si vas justa de tiempo, mejor 20 minutos que nada.", "note": "", "lift": "", "unit": "min", "sort": 73}, {"id": "MOVILIDAD", "grp": "Movilidad", "name": "Movilidad y estiramientos", "muscle": "Todo el cuerpo", "equip": "Peso corporal", "simple": "Cadera, tobillos, espalda alta y hombros, sin prisa.", "tip": "Respira lento y no fuerces el estiramiento.", "note": "", "lift": "", "unit": "min", "sort": 74}]$arc$::jsonb)
on conflict (id) do nothing;

